schweineroulade in sauce 52% (schweineroulade 44% (schweinefleisch 64%, gewürzgurken (gurken, wasser, branntweinessig, speisesalz), zwiebeln, paniermehl (weizenmehl, wasser, speisesalz, hefe), senf (wasser, senfsaaten, speisesalz, zucker, branntweinessig, gewürze), wasser, kartoffelstärke, speisesalz, traubenzucker, gewürze), wasser, zwiebeln, senf (wasser, senfsaaten, branntweinessig, speisesalz, gewürze), tomatenmark, stärke, gewürze, zucker, verdickungsmittel (cellulosegummi, guarkernmehl), sambal oelek (chili, paprika, wasser, speisesalz), rapsöl, sahne, karamellisierter zucker, speisesalz); 

kartoffelzubereitung 28 % (kartoffeln 65 %, wasser, zwiebeln, rapsöl, kräuter, verdickungsmittel (cellulosegummi, guarkernmehl), speisesalz, stärke, antioxidationsmittel (natriummetabisulfit, ascorbinsäure), gewürze);

rotkohlzubereitung 20% (rotkohl 70%, wasser, zucker, stärke, rapsöl, verdickungsmittel (cellulosegummi, guarkernmehl), antioxidationsmittel (ascorbinsäure), speisesalz, gewürze, branntweinessig, apfelsaftkonzentrat, johannisbeersaftkonzentrat).
